import { parseDate } from "./dateUtils";

// Distance par semaine (4 dernières semaines du mois sélectionné)
export const getWeeklyDistance = (sessions) => {
  const weeks = {};

  sessions.forEach((s) => {
    const { year, week } = parseDate(s.date);
    const key = `${year}-W${week}`;

    if (!weeks[key]) weeks[key] = 0;
    weeks[key] += s.distance;
  });

  // Transformer en tableau trié
  const arr = Object.keys(weeks)
    .map((key) => ({
      key,
      week: key.split("-W")[1],
      km: Number(weeks[key].toFixed(1)),
    }))
    .sort((a, b) => Number(a.week) - Number(b.week));

  // 🔥 Ne garder que les 4 dernières semaines
  const last4 = arr.slice(-4);

  // 🔥 Si moins de 4 semaines → compléter avec des semaines vides
  while (last4.length < 4) {
    last4.unshift({
      week: `S${last4.length + 1}`,
      km: 0,
    });
  }

  return last4;
};


// BPM repos / effort
export const getHeartRateSummary = (sessions) => {
  if (sessions.length === 0) return [];

  const avgRest = Math.round(
    sessions.reduce((sum, s) => sum + s.heartRate.min, 0) / sessions.length
  );

  const avgEffort = Math.round(
    sessions.reduce((sum, s) => sum + s.heartRate.max, 0) / sessions.length
  );

  return [
    { name: "Repos", bpm: avgRest },
    { name: "Effort", bpm: avgEffort },
  ];
};

// Donut sessions réalisées vs objectif
export const getDonutData = (sessions, goal = 6) => {
  const done = sessions.length;
  return [
    { name: "Réalisé", value: done },
    { name: "Restant", value: Math.max(goal - done, 0) },
  ];
};

export const getMonthlyAverageKm = (sessions) => {
  if (!sessions.length) return 0;

  const total = sessions.reduce((sum, s) => sum + s.distance, 0);
  return Number((total / sessions.length).toFixed(1));
};
